import React, { useState } from "react";
import { TextField, Button, Typography } from "@mui/material";
import axios from "axios";
import LoadingBar from "./LoadingBar";
import ScreenshotDisplay from "./ScreenshotDisplay";
import "./../styles/AdForm.css";

const AdForm: React.FC = () => {
  const [price, setPrice] = useState<string>("");
  const [description, setDescription] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault(); // Prevent form reload
    setLoading(true); // Show loading bar
    setError(null); // Reset any previous error

    try {
      const response = await axios.post("http://localhost:4000/postAd", {
        price,
        description,
      });

      const { message } = response.data;
      setScreenshot(message); // Set the screenshot to display
    } catch (err) {
      setError("Error: Failed to submit ad. Please try again.");
    } finally {
      setLoading(false); // Hide loading bar
    }
  };

  return (
    <div className="ad-form-container">
      <Typography variant="h4" gutterBottom>
        Publicar Anuncio
      </Typography>

      <form onSubmit={handleSubmit}>
        <TextField
          label="Precio"
          variant="outlined"
          value={price}
          onChange={(e) => setPrice(e.target.value)}
          fullWidth
          margin="normal"
        />

        <TextField
          label="Descripción"
          variant="outlined"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          multiline
          rows={4}
          fullWidth
          margin="normal"
        />

        <Button
          type="submit"
          variant="contained"
          color="primary"
          disabled={loading} // Disable button when loading
          fullWidth
        >
          Publicar
        </Button>
      </form>

      {/* Loading Bar */}
      {loading && <LoadingBar />}

      {/* Error Message */}
      {error && (
        <Typography color="error" className="error-message">
          {error}
        </Typography>
      )}

      {/* Screenshot Display */}
      {screenshot && <ScreenshotDisplay screenshot={screenshot} />}
    </div>
  );
};

export default AdForm;
